import React, { useState, useEffect } from 'react';
import Navigation from './components/Navigation';
import HomeView from './components/HomeView';
import PuppiesView from './components/PuppiesView';
import PuppyDetailView from './components/PuppyDetailView';
import FaqView from './components/FaqView';

export default function App() {
  const [currentView, setCurrentView] = useState('home');
  const [selectedPuppyId, setSelectedPuppyId] = useState(null);

  // State to hold dynamic data from MongoDB
  const [puppiesDatabase, setPuppiesDatabase] = useState([]);

  const [activeFilters, setActiveFilters] = useState({
    where: 'Everywhere',
    breeds: [],
    genders: []
  });

  // Fetch data when the app loads
  useEffect(() => {
    /* 
      TODO: Replace with your actual backend API endpoint
      Example for MongoDB/Express setup:

      fetch('http://localhost:5000/api/puppies')
        .then(response => response.json())
        .then(data => setPuppiesDatabase(data))
        .catch(error => console.error('Error fetching puppies:', error));
    */
  }, []);

  const updateFilter = (category, value) => {
    setActiveFilters(prev => {
      const newFilters = { ...prev };
      if (category === 'where') {
        newFilters.where = value;
      } else if (category === 'breed') {
        newFilters.breeds = prev.breeds.includes(value) 
          ? prev.breeds.filter(b => b !== value) 
          : [...prev.breeds, value];
      } else if (category === 'gender') {
        newFilters.genders = prev.genders.includes(value) 
          ? prev.genders.filter(g => g !== value) 
          : [...prev.genders, value];
      }
      return newFilters;
    });
  };

  const setFilterAndGo = (type, value) => {
    setActiveFilters({ where: 'Everywhere', breeds: [], genders: [] });
    updateFilter(type, value);
    setCurrentView('puppies');
  };

  const showPuppyDetail = (id) => {
    setSelectedPuppyId(id);
    setCurrentView('detail');
  };

  // Find the selected puppy from the dynamically loaded state
  const getSelectedPuppy = () => puppiesDatabase.find(p => p.id === selectedPuppyId || p._id === selectedPuppyId);

  return (
    <div className="font-sans antialiased bg-[#fff9f0] text-[#4a3b32] min-h-screen pb-20 selection:bg-[#8c4a2f] selection:text-white">
      <Navigation setCurrentView={setCurrentView} />

      {currentView === 'home' && (
        <HomeView setCurrentView={setCurrentView} setFilterAndGo={setFilterAndGo} />
      )}

      {currentView === 'puppies' && (
        <PuppiesView 
          puppies={puppiesDatabase} 
          activeFilters={activeFilters} 
          updateFilter={updateFilter} 
          showPuppyDetail={showPuppyDetail} 
        />
      )}

      {currentView === 'detail' && (
        <PuppyDetailView 
          puppy={getSelectedPuppy()} 
          goBack={() => setCurrentView('puppies')} 
        />
      )}

      {currentView === 'faq' && (
        <FaqView />
      )}
    </div>
  );
}
